@charset "UTF-8";

:root {
  --ink: #07060c;
  --ink-soft: #0d0b14;
  --paper: #f7eedb;
  --paper-dim: #c9bda8;
  --gold: #e9b763;
  --gold-bright: #ffdf9b;
  --gold-deep: #9c642b;
  --ember: #ff6a3d;
  --crimson: #d83f4c;
  --jade: #8fd9a8;
  --storm: #7be3f2;
  --line: rgba(233, 183, 99, 0.28);
  --line-soft: rgba(247, 238, 219, 0.1);
  --display: "Bodoni 72", "Bodoni MT", Didot, "Didot LT STD", "Playfair Display", Georgia, serif;
  --sans: "Avenir Next", Avenir, "Century Gothic", "Trebuchet MS", system-ui, sans-serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  overscroll-behavior: none;
  background: var(--ink);
}

body {
  position: relative;
  color: var(--paper);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}

button {
  font: inherit;
  color: inherit;
}

button:focus-visible {
  outline: 1px solid var(--gold-bright);
  outline-offset: 5px;
}

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  z-index: 0;
}

body[data-mode="playing"] #scene,
body[data-mode="dying"] #scene {
  cursor: none;
}

.atmosphere,
.grain {
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
}

.atmosphere {
  background:
    radial-gradient(ellipse 95% 80% at 50% 46%, transparent 48%, rgba(4, 4, 9, 0.32) 76%, rgba(3, 3, 7, 0.72) 100%),
    linear-gradient(180deg, rgba(4, 4, 9, 0.18), transparent 22%, transparent 80%, rgba(4, 4, 9, 0.34));
}

.grain {
  z-index: 2;
  opacity: 0.16;
  mix-blend-mode: soft-light;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%' height='100%' filter='url(%23n)' opacity='.55'/></svg>");
  background-size: 180px 180px;
  animation: grain-drift 0.4s steps(2) infinite;
}

@keyframes grain-drift {
  0% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(-1.6%, 1.2%, 0); }
  50% { transform: translate3d(1.1%, -1.4%, 0); }
  75% { transform: translate3d(1.4%, 0.7%, 0); }
  100% { transform: translate3d(-0.8%, -0.7%, 0); }
}

/* ── Chrome ─────────────────────────────────────────────── */

.topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 40;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding:
    calc(26px + var(--safe-top))
    calc(34px + var(--safe-right))
    0
    calc(34px + var(--safe-left));
  pointer-events: none;
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.topbar > * {
  pointer-events: auto;
}

.brand {
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
  transition: opacity 0.4s ease;
}

.brand-seal {
  display: grid;
  place-items: center;
  width: 40px;
  height: 46px;
  border: 1px solid rgba(216, 63, 76, 0.55);
  background: linear-gradient(160deg, rgba(216, 63, 76, 0.22), rgba(83, 19, 27, 0.12));
  color: #f2c4aa;
  font-family: "Hiragino Mincho ProN", "Yu Mincho", "Noto Serif CJK JP", serif;
  font-size: 21px;
  line-height: 1;
  box-shadow: inset 0 0 18px rgba(216, 63, 76, 0.12), 0 0 24px rgba(216, 63, 76, 0.08);
  position: relative;
  flex: 0 0 auto;
}

.brand-seal::before,
.brand-seal::after {
  content: "";
  position: absolute;
  background: rgba(233, 183, 99, 0.36);
}

.brand-seal::before {
  inset: 3px;
  border: 1px solid rgba(233, 183, 99, 0.16);
  background: transparent;
}

.brand-seal::after {
  display: none;
}

.brand-type {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.brand-kicker {
  color: var(--gold);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  white-space: nowrap;
  transition: opacity 0.3s ease;
}

.brand-name {
  color: rgba(247, 238, 219, 0.92);
  font-family: var(--display);
  font-size: 17px;
  font-weight: 600;
  letter-spacing: 0.14em;
  line-height: 1;
  white-space: nowrap;
}

.top-actions {
  display: flex;
  gap: 10px;
}

.round-button {
  position: relative;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 1px solid rgba(247, 238, 219, 0.17);
  border-radius: 50%;
  background: rgba(10, 9, 16, 0.38);
  color: rgba(247, 238, 219, 0.72);
  cursor: pointer;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: border-color 0.25s ease, color 0.25s ease, background 0.25s ease, transform 0.25s ease;
}

.round-button:hover {
  border-color: rgba(233, 183, 99, 0.6);
  background: rgba(35, 25, 24, 0.6);
  color: var(--gold-bright);
  transform: translateY(-1px);
}

.round-button:active {
  transform: scale(0.94);
}

.round-button .icon {
  width: 21px;
  height: 21px;
  grid-area: 1 / 1;
}

.icon-muted {
  opacity: 0;
  transform: scale(0.8);
  transition: opacity 0.2s ease, transform 0.2s ease;
}

body.is-muted .icon-sound {
  opacity: 0;
  transform: scale(0.8);
}

body.is-muted .icon-muted {
  opacity: 1;
  transform: scale(1);
}

.icon-sound {
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.pause-button {
  opacity: 0;
  visibility: hidden;
  transform: translateY(-5px);
  transition: opacity 0.3s ease, visibility 0.3s ease, transform 0.3s ease, border-color 0.25s ease, color 0.25s ease;
}

body[data-mode="playing"] .pause-button,
body[data-mode="paused"] .pause-button,
body[data-mode="dying"] .pause-button {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

body[data-mode="playing"] .brand-kicker,
body[data-mode="dying"] .brand-kicker {
  opacity: 0;
}

body[data-mode="playing"] .brand-seal,
body[data-mode="dying"] .brand-seal {
  width: 34px;
  height: 38px;
  font-size: 17px;
}

body[data-mode="playing"] .brand-name,
body[data-mode="dying"] .brand-name {
  font-size: 14px;
}

/* ── HUD ────────────────────────────────────────────────── */

.hud {
  position: fixed;
  top: calc(98px + var(--safe-top));
  left: calc(34px + var(--safe-left));
  right: calc(34px + var(--safe-right));
  z-index: 30;
  display: grid;
  grid-template-columns: 1fr minmax(280px, 420px) 1fr;
  align-items: start;
  gap: 24px;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-10px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}

body[data-mode="playing"] .hud,
body[data-mode="paused"] .hud,
body[data-mode="dying"] .hud {
  opacity: 1;
  transform: translateY(0);
}

body[data-mode="paused"] .hud,
body[data-mode="dying"] .hud {
  opacity: 0.42;
}

.hud-panel {
  position: relative;
  min-width: 126px;
  padding: 11px 17px 12px;
  background: linear-gradient(145deg, rgba(14, 12, 20, 0.68), rgba(8, 7, 13, 0.4));
  border: 1px solid rgba(233, 183, 99, 0.18);
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.hud-panel::before {
  content: "";
  position: absolute;
  top: 0;
  left: 14px;
  width: 50px;
  height: 1px;
  background: linear-gradient(90deg, var(--gold), transparent);
  opacity: 0.8;
}

.hud-label {
  display: block;
  margin-bottom: 3px;
  color: rgba(233, 183, 99, 0.7);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.3em;
}

.score-panel {
  justify-self: start;
}

.score-value {
  display: block;
  font-family: var(--display);
  font-size: clamp(27px, 2.6vw, 39px);
  font-weight: 500;
  line-height: 0.95;
  letter-spacing: 0.04em;
  color: var(--paper);
  font-variant-numeric: lining-nums tabular-nums;
  text-shadow: 0 0 24px rgba(255, 229, 174, 0.14);
}

.focus-panel {
  justify-self: end;
  text-align: right;
}

.focus-gems {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  height: 26px;
  align-items: center;
}

.focus-gem {
  display: block;
  width: 16px;
  height: 16px;
  background: linear-gradient(135deg, #ffe6af, #d79545 56%, #7f4820);
  clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%);
  filter: drop-shadow(0 0 7px rgba(233, 183, 99, 0.5));
  transition: opacity 0.4s ease, transform 0.4s ease, filter 0.4s ease;
}

.focus-gem:nth-child(2) {
  width: 19px;
  height: 19px;
}

.focus-gem.is-lost {
  opacity: 0.18;
  filter: none;
  transform: scale(0.65) rotate(45deg);
}

.focus-gem.is-breaking {
  animation: gem-break 0.5s ease;
}

@keyframes gem-break {
  0% { transform: scale(1.8); filter: drop-shadow(0 0 16px #ff5c45); opacity: 1; }
  100% { transform: scale(0.65) rotate(45deg); filter: none; opacity: 0.18; }
}

.chain-panel {
  justify-self: center;
  width: 100%;
  padding-top: 3px;
  transition: opacity 0.3s ease;
}

.chain-readout {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 10px;
  height: 36px;
}

.chain-title {
  color: rgba(247, 238, 219, 0.46);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.38em;
  transform: translateY(-2px);
}

.chain-count {
  color: var(--paper);
  font-family: var(--display);
  font-size: 34px;
  font-weight: 500;
  line-height: 1;
  min-width: 26px;
  text-align: center;
  font-variant-numeric: lining-nums tabular-nums;
  text-shadow: 0 0 26px rgba(255, 197, 105, 0.2);
  transition: color 0.25s ease, text-shadow 0.25s ease;
}

.chain-multiplier {
  color: var(--gold);
  font-family: var(--display);
  font-size: 16px;
  font-style: italic;
  letter-spacing: 0.03em;
  transform: translateY(-3px);
}

.chain-track {
  position: relative;
  height: 3px;
  width: 100%;
  background: rgba(247, 238, 219, 0.1);
  overflow: hidden;
  box-shadow: 0 0 14px rgba(233, 183, 99, 0.06);
}

.chain-fill {
  position: absolute;
  inset: 0;
  transform: scaleX(0);
  transform-origin: 0 50%;
  background: linear-gradient(90deg, rgba(233, 183, 99, 0.6), var(--gold-bright));
  box-shadow: 0 0 10px rgba(255, 212, 128, 0.7);
  transition: transform 0.08s linear;
}

.chain-notch {
  position: absolute;
  top: 0;
  width: 1px;
  height: 100%;
  background: rgba(8, 7, 13, 0.65);
}

.chain-meta {
  display: flex;
  justify-content: space-between;
  margin-top: 7px;
  color: rgba(247, 238, 219, 0.38);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.22em;
}

#chainStatus {
  transition: color 0.25s ease;
}

body.chain-hot #chainStatus {
  color: var(--gold);
}

body.chain-blaze #chainStatus {
  color: #ff9a66;
  text-shadow: 0 0 10px rgba(255, 106, 61, 0.55);
}

body.chain-storm #chainStatus {
  color: var(--storm);
  text-shadow: 0 0 12px rgba(123, 227, 242, 0.6);
}

body.chain-dragon #chainStatus {
  color: var(--gold-bright);
  text-shadow: 0 0 14px rgba(255, 223, 155, 0.8);
}

body.chain-hot .chain-count {
  color: var(--gold-bright);
  text-shadow: 0 0 24px rgba(255, 197, 105, 0.42);
}

body.chain-blaze .chain-count,
body.chain-storm .chain-count {
  color: #fff4dd;
  text-shadow: 0 0 28px rgba(255, 130, 70, 0.55);
}

body.chain-dragon .chain-count {
  color: #fff7de;
  text-shadow: 0 0 20px #ffd47a, 0 0 46px rgba(255, 185, 75, 0.7);
}

body.chain-hot .chain-fill {
  background: linear-gradient(90deg, #c17a36, #ffd982);
}

body.chain-blaze .chain-fill {
  background: linear-gradient(90deg, #ff6a3d, #ffd16b);
  box-shadow: 0 0 16px rgba(255, 106, 61, 0.85);
}

body.chain-storm .chain-fill {
  background: linear-gradient(90deg, #3aa8c6, #a8f8ff);
  box-shadow: 0 0 18px rgba(123, 227, 242, 0.9);
}

body.chain-dragon .chain-fill {
  background: linear-gradient(90deg, #ff9a3d, #fff6cf, #ff9a3d);
  box-shadow: 0 0 20px rgba(255, 223, 155, 1);
}

/* ── Screens ────────────────────────────────────────────── */

.screens {
  position: fixed;
  inset: 0;
  z-index: 25;
  pointer-events: none;
}

.screen {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(94px + var(--safe-top)) calc(30px + var(--safe-right)) calc(38px + var(--safe-bottom)) calc(30px + var(--safe-left));
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.55s ease, visibility 0.55s ease;
}

.screen.is-active {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.menu-screen {
  align-items: center;
  justify-content: center;
}

.menu-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 42% 46% at 50% 47%, rgba(5, 4, 9, 0.3) 0%, rgba(5, 4, 9, 0.04) 64%, transparent 74%),
    linear-gradient(180deg, rgba(4, 4, 9, 0.16), transparent 30%, transparent 72%, rgba(4, 4, 9, 0.2));
  pointer-events: none;
}

.menu-inner {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  width: min(920px, 100%);
  margin-top: -1.5vh;
}

.menu-kicker {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: clamp(20px, 3.2vh, 38px);
  color: rgba(233, 183, 99, 0.72);
  font-size: clamp(7px, 0.65vw, 9px);
  font-weight: 700;
  letter-spacing: 0.38em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: 0;
  animation: menu-rise 0.9s 0.12s ease forwards;
}

.kicker-rule {
  display: block;
  width: clamp(24px, 4vw, 64px);
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(233, 183, 99, 0.55));
}

.kicker-rule:last-child {
  transform: scaleX(-1);
}

.title-wrap {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.title-sun {
  position: absolute;
  top: 47%;
  left: 50%;
  width: clamp(220px, 34vw, 450px);
  aspect-ratio: 1;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background:
    radial-gradient(circle at 48% 44%, rgba(205, 55, 60, 0.5) 0%, rgba(165, 40, 48, 0.32) 44%, rgba(120, 27, 36, 0.08) 68%, transparent 71%);
  filter: blur(6px);
  box-shadow: inset 0 0 30px rgba(255, 170, 112, 0.25);
  opacity: 0;
  animation: sun-bloom 2.1s 0.45s ease forwards;
}

.title-sun::after {
  content: "";
  position: absolute;
  inset: 8%;
  border-radius: 50%;
  border: 1px solid rgba(255, 200, 140, 0.1);
}

@keyframes sun-bloom {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.82); }
  100% { opacity: 0.78; transform: translate(-50%, -50%) scale(1); }
}

.title-jp {
  position: absolute;
  top: 5%;
  left: 50%;
  transform: translateX(-50%);
  z-index: 2;
  margin: 0;
  color: rgba(247, 238, 219, 0.36);
  font-family: "Hiragino Mincho ProN", "Yu Mincho", "Noto Serif CJK JP", serif;
  font-size: clamp(9px, 0.85vw, 12px);
  letter-spacing: 0.9em;
  text-indent: 0.9em;
  white-space: nowrap;
  opacity: 0;
  animation: menu-rise 1.1s 0.8s ease forwards;
}

.game-title {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  margin: 0;
  font-family: var(--display);
  font-weight: 500;
  font-size: clamp(90px, 13.2vw, 190px);
  line-height: 0.69;
  letter-spacing: -0.045em;
  text-transform: uppercase;
  transform: scale(0.97);
  opacity: 0;
  filter: blur(6px);
  animation: title-arrive 1.35s 0.22s cubic-bezier(0.16, 0.9, 0.25, 1) forwards;
}

@keyframes title-arrive {
  0% { opacity: 0; transform: scale(0.94) translateY(20px); filter: blur(10px); }
  100% { opacity: 1; transform: scale(1) translateY(0); filter: blur(0); }
}

.title-blade {
  display: block;
  color: var(--paper);
  text-shadow:
    0 2px 0 rgba(0, 0, 0, 0.25),
    0 8px 42px rgba(0, 0, 0, 0.72),
    0 0 70px rgba(255, 230, 180, 0.08);
}

.title-chain {
  display: block;
  margin-top: 0.03em;
  padding-right: 0.02em;
  color: transparent;
  background: linear-gradient(177deg, #fff8e9 8%, #f5d698 38%, #dfa451 67%, #9c642b 98%);
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 7px 22px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 34px rgba(233, 183, 99, 0.11));
  transform: translateX(0.045em);
}

.title-stroke {
  position: absolute;
  bottom: 3%;
  left: 50%;
  width: 74%;
  height: 1px;
  transform: translateX(-50%) scaleX(0);
  transform-origin: center;
  background: linear-gradient(90deg, transparent, rgba(233, 183, 99, 0.64), transparent);
  box-shadow: 0 0 18px rgba(233, 183, 99, 0.32);
  animation: stroke-in 1.2s 1.05s cubic-bezier(0.2, 0.9, 0.2, 1) forwards;
}

@keyframes stroke-in {
  to { transform: translateX(-50%) scaleX(1); }
}

.tagline {
  margin: clamp(25px, 4.8vh, 48px) 0 0;
  color: rgba(247, 238, 219, 0.58);
  font-family: var(--display);
  font-size: clamp(14px, 1.25vw, 18px);
  font-style: italic;
  letter-spacing: 0.04em;
  opacity: 0;
  animation: menu-rise 1s 0.72s ease forwards;
}

.play-cluster {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  margin-top: clamp(24px, 4.2vh, 43px);
  opacity: 0;
  animation: menu-rise 1s 0.95s ease forwards;
}

.play-button {
  position: relative;
  display: grid;
  place-items: center;
  width: clamp(70px, 6vw, 84px);
  height: clamp(70px, 6vw, 84px);
  padding: 0;
  border: 1px solid rgba(233, 183, 99, 0.62);
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 38%, rgba(255, 220, 157, 0.15), transparent 54%),
    rgba(13, 10, 17, 0.6);
  color: var(--gold-bright);
  cursor: pointer;
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  box-shadow:
    0 0 0 7px rgba(233, 183, 99, 0.045),
    0 0 44px rgba(233, 183, 99, 0.13),
    inset 0 0 24px rgba(233, 183, 99, 0.07);
  transition: transform 0.35s cubic-bezier(0.18, 0.9, 0.24, 1), border-color 0.3s ease, box-shadow 0.35s ease;
}

.play-button::before {
  content: "";
  position: absolute;
  inset: 8px;
  border: 1px solid rgba(233, 183, 99, 0.22);
  border-radius: 50%;
  transition: border-color 0.35s ease, transform 0.35s ease;
}

.play-button:hover {
  transform: scale(1.07);
  border-color: var(--gold-bright);
  box-shadow:
    0 0 0 9px rgba(233, 183, 99, 0.06),
    0 0 56px rgba(233, 183, 99, 0.26),
    inset 0 0 35px rgba(233, 183, 99, 0.13);
}

.play-button:hover::before {
  border-color: rgba(255, 223, 155, 0.5);
  transform: rotate(45deg);
}

.play-button:active {
  transform: scale(0.97);
}

.play-ring {
  position: absolute;
  inset: -18px;
  border: 1px solid rgba(233, 183, 99, 0.14);
  border-radius: 50%;
  animation: ring-breathe 3.2s ease-in-out infinite;
}

@keyframes ring-breathe {
  0%, 100% { transform: scale(0.96); opacity: 0.4; }
  50% { transform: scale(1.06); opacity: 0.8; }
}

.play-glyph {
  display: block;
  width: 32%;
  margin-left: 8%;
  filter: drop-shadow(0 0 10px rgba(255, 223, 155, 0.45));
}

.play-glyph svg {
  display: block;
  width: 100%;
  height: auto;
  fill: currentColor;
}

.play-word {
  color: rgba(233, 183, 99, 0.72);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.4em;
  text-indent: 0.4em;
}

.menu-hint {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 13px;
  max-width: 660px;
  margin: clamp(21px, 3.6vh, 36px) 0 0;
  color: rgba(247, 238, 219, 0.42);
  font-size: clamp(9px, 0.72vw, 11px);
  font-weight: 500;
  letter-spacing: 0.08em;
  line-height: 1.7;
  opacity: 0;
  animation: menu-rise 1s 1.15s ease forwards;
}

.menu-hint b {
  color: rgba(233, 183, 99, 0.45);
  font-weight: 400;
}

.menu-records {
  display: flex;
  align-items: center;
  gap: clamp(18px, 2.2vw, 30px);
  margin-top: clamp(16px, 2.8vh, 27px);
  color: rgba(247, 238, 219, 0.3);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.27em;
  opacity: 0;
  animation: menu-rise 1s 1.3s ease forwards;
}

.menu-records strong {
  margin-left: 7px;
  color: rgba(247, 238, 219, 0.72);
  font-family: var(--display);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.04em;
  font-variant-numeric: tabular-nums;
}

.menu-records i {
  width: 1px;
  height: 14px;
  background: rgba(247, 238, 219, 0.16);
}

.menu-footer {
  position: absolute;
  left: calc(34px + var(--safe-left));
  right: calc(34px + var(--safe-right));
  bottom: calc(24px + var(--safe-bottom));
  display: flex;
  justify-content: space-between;
  gap: 20px;
  color: rgba(247, 238, 219, 0.2);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.24em;
}

.footer-mark {
  color: rgba(233, 183, 99, 0.24);
  font-family: "Hiragino Mincho ProN", "Yu Mincho", serif;
  letter-spacing: 0.55em;
  text-indent: 0.55em;
}

@keyframes menu-rise {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ── Modals ─────────────────────────────────────────────── */

.pause-screen,
.over-screen {
  z-index: 35;
  background: rgba(4, 4, 9, 0.48);
  backdrop-filter: blur(6px) saturate(0.8);
  -webkit-backdrop-filter: blur(6px) saturate(0.8);
}

.modal {
  position: relative;
  width: min(520px, 100%);
  padding: clamp(34px, 4.4vw, 52px) clamp(27px, 4vw, 54px) clamp(31px, 3.8vw, 43px);
  text-align: center;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(233, 183, 99, 0.08), transparent 55%),
    linear-gradient(158deg, rgba(24, 20, 27, 0.94), rgba(8, 7, 12, 0.97));
  border: 1px solid rgba(233, 183, 99, 0.23);
  clip-path: polygon(0 0, calc(100% - 24px) 0, 100% 24px, 100% 100%, 24px 100%, 0 calc(100% - 24px));
  box-shadow:
    0 35px 100px rgba(0, 0, 0, 0.7),
    inset 0 1px 0 rgba(255, 238, 202, 0.05);
  transform: translateY(16px) scale(0.985);
  transition: transform 0.55s cubic-bezier(0.16, 0.9, 0.25, 1);
}

.screen.is-active .modal {
  transform: translateY(0) scale(1);
}

.modal::before,
.modal::after {
  content: "";
  position: absolute;
  width: 50px;
  height: 1px;
  top: 20px;
  background: linear-gradient(90deg, var(--gold), transparent);
  opacity: 0.45;
}

.modal::before {
  left: 27px;
}

.modal::after {
  right: 27px;
  transform: scaleX(-1);
}

.modal-kicker {
  margin: 0 0 12px;
  color: rgba(233, 183, 99, 0.7);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.36em;
  text-transform: uppercase;
}

.modal-title {
  margin: 0;
  color: var(--paper);
  font-family: var(--display);
  font-size: clamp(44px, 6vw, 76px);
  font-weight: 500;
  line-height: 0.92;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  text-shadow: 0 8px 40px rgba(0, 0, 0, 0.6);
}

.over-modal .modal-title {
  font-size: clamp(38px, 5.4vw, 65px);
}

.modal-copy {
  max-width: 390px;
  margin: 16px auto 0;
  color: rgba(247, 238, 219, 0.48);
  font-family: var(--display);
  font-size: 15px;
  font-style: italic;
  line-height: 1.5;
}

.modal-actions {
  display: flex;
  justify-content: center;
  gap: 11px;
  margin-top: 31px;
}

.button {
  position: relative;
  min-width: 128px;
  min-height: 47px;
  padding: 14px 24px;
  border: 1px solid transparent;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  cursor: pointer;
  clip-path: polygon(0 0, calc(100% - 9px) 0, 100% 9px, 100% 100%, 9px 100%, 0 calc(100% - 9px));
  transition: transform 0.25s ease, background 0.25s ease, border-color 0.25s ease, color 0.25s ease;
}

.button:hover {
  transform: translateY(-2px);
}

.button:active {
  transform: translateY(0) scale(0.98);
}

.button-primary {
  color: #1c120b;
  background: linear-gradient(160deg, #ffe6b0, #e9b763 54%, #bf8037);
  border-color: rgba(255, 230, 176, 0.6);
  box-shadow: 0 8px 26px rgba(233, 183, 99, 0.17);
}

.button-primary:hover {
  background: linear-gradient(160deg, #fff1ca, #f3c879 54%, #cb8a3f);
}

.button-quiet {
  color: rgba(247, 238, 219, 0.67);
  background: rgba(247, 238, 219, 0.025);
  border-color: rgba(247, 238, 219, 0.16);
}

.button-quiet:hover {
  color: var(--paper);
  border-color: rgba(233, 183, 99, 0.42);
  background: rgba(233, 183, 99, 0.06);
}

.result-grid {
  display: grid;
  grid-template-columns: 1.18fr 1fr;
  gap: 1px;
  margin-top: 31px;
  background: rgba(233, 183, 99, 0.12);
  border: 1px solid rgba(233, 183, 99, 0.14);
  text-align: left;
}

.result-cell {
  padding: 14px 17px 15px;
  background: rgba(7, 6, 11, 0.8);
}

.result-cell span {
  display: block;
  margin-bottom: 5px;
  color: rgba(247, 238, 219, 0.31);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.27em;
}

.result-cell strong {
  color: rgba(247, 238, 219, 0.9);
  font-family: var(--display);
  font-size: 23px;
  font-weight: 500;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.result-main {
  grid-row: span 2;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 19px 20px;
}

.result-main strong {
  color: var(--gold-bright);
  font-size: clamp(38px, 5.5vw, 55px);
  text-shadow: 0 0 35px rgba(233, 183, 99, 0.2);
}

.new-record {
  display: none;
  margin: 13px 0 0;
  color: var(--gold);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.34em;
  text-indent: 0.34em;
}

.new-record.is-visible {
  display: block;
  animation: record-glow 1.9s ease-in-out infinite;
}

@keyframes record-glow {
  50% { opacity: 0.55; text-shadow: 0 0 16px rgba(255, 212, 126, 0.6); }
}

/* ── Combo banner ───────────────────────────────────────── */

.combo-banner {
  position: fixed;
  top: 36%;
  left: 50%;
  z-index: 24;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  transform: translate(-50%, -50%) scale(0.88);
  opacity: 0;
  pointer-events: none;
  text-align: center;
  transition: opacity 0.18s ease, transform 0.3s cubic-bezier(0.16, 0.9, 0.25, 1);
}

.combo-banner.is-visible {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1);
}

.combo-banner strong {
  color: var(--gold-bright);
  font-family: var(--display);
  font-size: clamp(32px, 4.4vw, 58px);
  font-weight: 500;
  font-style: italic;
  line-height: 1;
  letter-spacing: 0.02em;
  text-shadow: 0 0 20px rgba(255, 193, 86, 0.4), 0 4px 30px rgba(0, 0, 0, 0.8);
}

.combo-banner small {
  color: rgba(247, 238, 219, 0.55);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.35em;
  text-indent: 0.35em;
}

.combo-banner.is-storm strong {
  color: #b8f8ff;
  text-shadow: 0 0 26px rgba(123, 227, 242, 0.7), 0 4px 30px rgba(0, 0, 0, 0.8);
}

.combo-banner.is-dragon strong {
  color: #fff7dd;
  text-shadow: 0 0 18px #ffd47a, 0 0 55px rgba(255, 164, 56, 0.8), 0 4px 30px rgba(0, 0, 0, 0.8);
}

.combo-flare {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 180px;
  height: 1px;
  transform: translate(-50%, -50%);
  background: linear-gradient(90deg, transparent, rgba(255, 223, 155, 0.65), transparent);
  box-shadow: 0 0 20px rgba(255, 196, 91, 0.7);
}

/* ── Side marks ─────────────────────────────────────────── */

.side-mark {
  position: fixed;
  top: 50%;
  z-index: 20;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 15px;
  transform: translateY(-50%);
  color: rgba(247, 238, 219, 0.18);
  pointer-events: none;
  opacity: 0;
  animation: side-in 1.6s 1.2s ease forwards;
}

@keyframes side-in {
  to { opacity: 1; }
}

.side-mark-left {
  left: calc(32px + var(--safe-left));
}

.side-mark-right {
  right: calc(32px + var(--safe-right));
}

.side-mark span {
  color: rgba(233, 183, 99, 0.35);
  font-family: "Hiragino Mincho ProN", "Yu Mincho", "Noto Serif CJK JP", serif;
  font-size: 18px;
  letter-spacing: 0.32em;
  writing-mode: vertical-rl;
  text-orientation: upright;
}

.side-mark small {
  color: rgba(247, 238, 219, 0.17);
  font-size: 6px;
  font-weight: 700;
  letter-spacing: 0.24em;
  writing-mode: vertical-rl;
  text-orientation: mixed;
}

.side-mark i {
  display: block;
  width: 1px;
  height: 44px;
  background: linear-gradient(180deg, transparent, rgba(233, 183, 99, 0.28), transparent);
}

.side-mark-right small {
  line-height: 1.2;
}

.rotate-note {
  position: fixed;
  left: 50%;
  bottom: calc(16px + var(--safe-bottom));
  z-index: 60;
  display: none;
  transform: translateX(-50%);
  padding: 8px 14px;
  border: 1px solid rgba(233, 183, 99, 0.22);
  background: rgba(8, 7, 12, 0.82);
  color: rgba(247, 238, 219, 0.55);
  font-size: 8px;
  letter-spacing: 0.14em;
  white-space: nowrap;
  pointer-events: none;
}

body[data-mode="menu"] .side-mark,
body[data-mode="gameover"] .side-mark {
  display: none;
}

/* ── Responsive ─────────────────────────────────────────── */

