};

export const FRUIT_KEYS = Object.keys(FRUIT_TYPES);

export function randomFrom(list, random = Math.random) {
  return list[Math.floor(random() * list.length)];
}

export function makeFruit(type, x, y, radius, vx, vy, seed = Math.random() * 1e9) {
  return {
    type,
    x,
    y,
    vx,
    vy,
    radius: radius * FRUIT_TYPES[type].radius,
    rot: (seed % 1000) / 1000 * TAU,
    rotSpeed: ((seed % 17) / 17 - 0.5) * 2.4,
    seed: Math.floor(seed),
    age: 0
  };
}

function seeded(seed) {
  let value = seed >>> 0;
  return () => {
    value = (value * 1664525 + 1013904223) >>> 0;
    return value / 4294967296;
  };
}

function ellipse(ctx, x, y, rx, ry) {
  ctx.beginPath();
  ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
}

function bodyPath(ctx, r, shape) {
  ctx.beginPath();
  if (shape === "apple") {
    ctx.moveTo(0, -r * 0.73);
    ctx.bezierCurveTo(-r * 0.22, -r * 0.96, -r * 0.58, -r * 0.88, -r * 0.7, -r * 0.52);
    ctx.bezierCurveTo(-r * 1.06, r * 0.12, -r * 0.8, r * 0.98, 0, r);
    ctx.bezierCurveTo(r * 0.8, r * 0.98, r * 1.06, r * 0.12, r * 0.7, -r * 0.52);
    ctx.bezierCurveTo(r * 0.58, -r * 0.88, r * 0.22, -r * 0.96, 0, -r * 0.73);
  } else if (shape === "kiwi") {
    ctx.ellipse(0, 0, r * 0.86, r, 0, 0, TAU);
  } else if (shape === "lemon") {
    ctx.moveTo(-r * 1.06, 0);
    ctx.bezierCurveTo(-r * 0.74, -r * 0.8, r * 0.72, -r * 0.8, r * 1.06, 0);
    ctx.bezierCurveTo(r * 0.72, r * 0.8, -r * 0.74, r * 0.8, -r * 1.06, 0);
  } else if (shape === "dragon") {
    ctx.ellipse(0, 0, r * 0.93, r * 1.02, 0, 0, TAU);
  } else if (shape === "pomegranate") {
    ctx.ellipse(0, r * 0.03, r * 0.95, r * 0.98, 0, 0, TAU);
  } else {
    ctx.ellipse(0, 0, r, r * 0.98, 0, 0, TAU);
  }
  ctx.closePath();
}

function skinGradient(ctx, r, type) {
  const [light, mid, dark] = type.skin;
  const gradient = ctx.createRadialGradient(-r * 0.36, -r * 0.48, r * 0.06, 0, r * 0.08, r * 1.17);
  gradient.addColorStop(0, light);
  gradient.addColorStop(0.46, mid);
  gradient.addColorStop(1, dark);
  return gradient;
}

function drawLeaf(ctx, r, angle, color, offsetY = -r * 0.82) {
  ctx.save();
  ctx.translate(0, offsetY);
  ctx.rotate(angle);
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.bezierCurveTo(r * 0.06, -r * 0.2, r * 0.42, -r * 0.34, r * 0.62, -r * 0.2);
  ctx.bezierCurveTo(r * 0.48, r * 0.04, r * 0.15, r * 0.1, 0, 0);
  ctx.fill();
  ctx.strokeStyle = "rgba(18, 47, 20, 0.38)";
  ctx.lineWidth = Math.max(1, r * 0.022);
  ctx.beginPath();
  ctx.moveTo(r * 0.06, -r * 0.01);
  ctx.quadraticCurveTo(r * 0.34, -r * 0.18, r * 0.56, -r * 0.2);
  ctx.stroke();
  ctx.restore();
}

function drawStem(ctx, r, bend = 0.16) {
  ctx.strokeStyle = "#57391f";
  ctx.lineWidth = Math.max(2, r * 0.085);
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(0, -r * 0.78);
  ctx.quadraticCurveTo(r * bend, -r * 1.03, r * (bend + 0.1), -r * 1.12);
  ctx.stroke();
  ctx.strokeStyle = "rgba(255, 220, 165, 0.22)";
  ctx.lineWidth = Math.max(0.8, r * 0.02);
  ctx.beginPath();
  ctx.moveTo(-r * 0.02, -r * 0.79);
  ctx.quadraticCurveTo(r * (bend - 0.03), -r * 1.01, r * (bend + 0.06), -r * 1.1);
  ctx.stroke();
}

function drawRim(ctx, r, shape, color = "rgba(255, 242, 208, 0.17)") {
  ctx.save();
  bodyPath(ctx, r * 0.985, shape);
  ctx.strokeStyle = color;
  ctx.lineWidth = Math.max(1, r * 0.026);
  ctx.stroke();
  ctx.restore();
}

function drawGloss(ctx, r, shape, strength = 0.19) {
  ctx.save();
  bodyPath(ctx, r, shape);
  ctx.clip();
  const gloss = ctx.createLinearGradient(-r * 0.7, -r * 0.9, r * 0.18, r * 0.55);
  gloss.addColorStop(0, `rgba(255, 249, 228, ${strength})`);
  gloss.addColorStop(0.4, "rgba(255, 249, 228, 0.035)");
  gloss.addColorStop(1, "rgba(255, 249, 228, 0)");
  ctx.fillStyle = gloss;
  ctx.beginPath();
  ctx.ellipse(-r * 0.3, -r * 0.38, r * 0.62, r * 0.36, -0.46, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawDragonScales(ctx, r, seed) {
  const random = seeded(seed + 81);
  for (let i = 0; i < 9; i += 1) {
    const angle = -Math.PI * 0.92 + i * 0.28 + (random() - 0.5) * 0.12;
    const cx = Math.cos(angle) * r * 0.75;
    const cy = Math.sin(angle) * r * 0.84;
    const length = r * (0.33 + random() * 0.22);
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle + Math.PI * 0.5);
    ctx.fillStyle = i % 2 ? "#8bcf69" : "#6bab51";
    ctx.beginPath();
    ctx.moveTo(-r * 0.16, r * 0.08);
    ctx.quadraticCurveTo(-r * 0.02, -length * 0.8, 0, -length);
    ctx.quadraticCurveTo(r * 0.11, -length * 0.52, r * 0.16, r * 0.08);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
}

function drawSkinDetails(ctx, type, r, seed, shape) {
  const random = seeded(seed + 7);
  ctx.save();
  bodyPath(ctx, r, shape);
  ctx.clip();

  if (type === FRUIT_TYPES.watermelon) {
    for (let i = -3; i <= 3; i += 1) {
      const x = i * r * 0.245;
      ctx.strokeStyle = i % 2 === 0 ? "rgba(9, 48, 28, 0.63)" : "rgba(9, 48, 28, 0.42)";
      ctx.lineWidth = r * (i % 2 === 0 ? 0.105 : 0.06);
      ctx.beginPath();
      ctx.moveTo(x - r * 0.05, -r * 0.96);
      ctx.bezierCurveTo(x + r * 0.12, -r * 0.4, x + r * 0.14, r * 0.35, x - r * 0.08, r * 0.97);
      ctx.stroke();
    }
    for (let i = 0; i < 3; i += 1) {
      ctx.fillStyle = "rgba(198, 235, 159, 0.16)";
      ellipse(ctx, -r * 0.48 + i * r * 0.4, r * 0.55, r * 0.06, r * 0.14);
      ctx.fill();
    }
  } else if (type === FRUIT_TYPES.orange || type === FRUIT_TYPES.lemon) {
    for (let i = 0; i < 31; i += 1) {
      const angle = random() * TAU;
      const distance = Math.sqrt(random()) * r * 0.88;
      const x = Math.cos(angle) * distance;
      const y = Math.sin(angle) * distance;
      ctx.fillStyle = i % 3 ? "rgba(112, 57, 8, 0.2)" : "rgba(255, 248, 200, 0.26)";
      ellipse(ctx, x, y, r * 0.017, r * 0.013);
      ctx.fill();
    }
    ctx.strokeStyle = "rgba(133, 73, 15, 0.18)";
    ctx.lineWidth = r * 0.03;
    ctx.beginPath();
    ctx.arc(r * 0.15, r * 0.08, r * 0.42, -0.8, 1.75);
    ctx.stroke();
  } else if (type === FRUIT_TYPES.apple) {
    for (let i = 0; i < 7; i += 1) {
      const x = (random() - 0.5) * r * 1.4;
      ctx.strokeStyle = "rgba(97, 22, 34, 0.16)";
      ctx.lineWidth = r * 0.025;
      ctx.beginPath();
      ctx.moveTo(x, -r * 0.7);
      ctx.quadraticCurveTo(x + r * 0.13, 0, x + (random() - 0.5) * r * 0.1, r * 0.72);
      ctx.stroke();
    }
    ctx.fillStyle = "rgba(91, 20, 35, 0.24)";
    ellipse(ctx, -r * 0.14, -r * 0.7, r * 0.2, r * 0.07);
    ctx.fill();
  } else if (type === FRUIT_TYPES.kiwi) {
    for (let i = 0; i < 54; i += 1) {
      const angle = random() * TAU;
      const distance = r * (0.55 + random() * 0.4);
      const x = Math.cos(angle) * distance * 0.87;
      const y = Math.sin(angle) * distance;
      ctx.strokeStyle = i % 4 ? "rgba(58, 38, 22, 0.36)" : "rgba(222, 194, 157, 0.23)";
      ctx.lineWidth = r * 0.018;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + Math.cos(angle) * r * 0.09, y + Math.sin(angle) * r * 0.09);
      ctx.stroke();
    }
  } else if (type === FRUIT_TYPES.plum) {
    const bloom = ctx.createRadialGradient(-r * 0.25, -r * 0.3, 0, -r * 0.25, -r * 0.3, r * 0.9);
    bloom.addColorStop(0, "rgba(220, 194, 238, 0.27)");
    bloom.addColorStop(1, "rgba(220, 194, 238, 0)");
    ctx.fillStyle = bloom;
    ctx.fillRect(-r, -r, r * 2, r * 2);
    ctx.strokeStyle = "rgba(48, 20, 62, 0.3)";
    ctx.lineWidth = r * 0.02;
    ctx.beginPath();
    ctx.moveTo(-r * 0.06, -r * 0.7);
    ctx.quadraticCurveTo(r * 0.05, 0, -r * 0.02, r * 0.68);
    ctx.stroke();
  } else if (type === FRUIT_TYPES.pomegranate) {
    for (let i = 0; i < 18; i += 1) {
      const x = (random() - 0.5) * r * 1.5;
      const y = (random() - 0.5) * r * 1.5;
      ctx.fillStyle = i % 3 ? "rgba(87, 12, 31, 0.23)" : "rgba(255, 168, 126, 0.14)";
      ellipse(ctx, x, y, r * (0.025 + random() * 0.035), r * 0.02);
      ctx.fill();
    }
  }

  ctx.restore();

  if (type === FRUIT_TYPES.watermelon) {
    drawStem(ctx, r, 0.08);
  } else if (type === FRUIT_TYPES.orange) {
    drawStem(ctx, r * 0.9, 0.12);
    drawLeaf(ctx, r, -0.9, "rgba(67, 127, 58, 0.92)", -r * 0.79);
  } else if (type === FRUIT_TYPES.apple) {
    drawStem(ctx, r * 0.92, 0.16);
    drawLeaf(ctx, r, 0.72, "rgba(74, 134, 61, 0.95)", -r * 0.79);
  } else if (type === FRUIT_TYPES.kiwi) {
    drawStem(ctx, r * 0.8, 0.1);
  } else if (type === FRUIT_TYPES.lemon) {
    drawLeaf(ctx, r * 0.9, -0.8, "rgba(75, 137, 60, 0.9)", -r * 0.77);
  } else if (type === FRUIT_TYPES.plum) {
    drawStem(ctx, r * 0.9, 0.14);
    drawLeaf(ctx, r * 0.9, 0.82, "rgba(72, 126, 57, 0.86)", -r * 0.75);
  } else if (type === FRUIT_TYPES.dragonfruit) {
    drawDragonScales(ctx, r, seed);
  } else if (type === FRUIT_TYPES.pomegranate) {
    ctx.fillStyle = "#7d182d";
    ctx.beginPath();
    ctx.moveTo(-r * 0.27, -r * 0.84);
    ctx.lineTo(-r * 0.18, -r * 1.14);
    ctx.lineTo(-r * 0.04, -r * 0.91);
    ctx.lineTo(0, -r * 1.2);
    ctx.lineTo(r * 0.12, -r * 0.9);
    ctx.lineTo(r * 0.28, -r * 1.1);
    ctx.lineTo(r * 0.3, -r * 0.79);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "rgba(255, 180, 137, 0.2)";
    ctx.lineWidth = r * 0.02;
    ctx.stroke();
  }
}

function drawBody(ctx, type, r, seed, shape, shadow = true) {
  ctx.save();
  if (shadow) {
    ctx.shadowColor = "rgba(0, 0, 0, 0.48)";
    ctx.shadowBlur = r * 0.72;
    ctx.shadowOffsetY = r * 0.28;
  }
  bodyPath(ctx, r, shape);
  ctx.fillStyle = skinGradient(ctx, r, type);
  ctx.fill();
  ctx.restore();

  drawSkinDetails(ctx, type, r, seed, shape);
  drawRim(ctx, r, shape);
  drawGloss(ctx, r, shape, type === FRUIT_TYPES.lemon ? 0.26 : 0.17);
}

export function drawFruit(ctx, fruit) {
  const type = FRUIT_TYPES[fruit.type];
  ctx.save();
  ctx.translate(fruit.x, fruit.y);
  ctx.rotate(fruit.rot);
  drawBody(ctx, type, fruit.radius, fruit.seed, type.shape, true);
  ctx.restore();
}

function cutFaceGradient(ctx, r, type) {
  const [light, mid, dark] = type.flesh;
  const gradient = ctx.createLinearGradient(-r * 0.7, 0, r * 0.7, 0);
  gradient.addColorStop(0, dark);
  gradient.addColorStop(0.42, mid);
  gradient.addColorStop(0.56, light);
  gradient.addColorStop(0.78, mid);
  gradient.addColorStop(1, dark);
  return gradient;
}

function drawCutDetails(ctx, type, r, offset, side) {
  const depth = side > 0 ? 1 : -1;
  const y = offset + depth * r * 0.06;
  ctx.save();

  if (type === FRUIT_TYPES.watermelon || type === FRUIT_TYPES.dragonfruit) {
    const count = type === FRUIT_TYPES.watermelon ? 6 : 7;
    for (let i = 0; i < count; i += 1) {
      const x = -r * 0.62 + (i / (count - 1)) * r * 1.24;
      ctx.fillStyle = type.pip;
      ellipse(ctx, x, y + depth * ((i % 2) * r * 0.06), r * 0.032, r * 0.056);
      ctx.fill();
    }
  } else if (type === FRUIT_TYPES.orange || type === FRUIT_TYPES.lemon) {
    ctx.strokeStyle = "rgba(158, 89, 19, 0.34)";
    ctx.lineWidth = Math.max(1, r * 0.018);
    for (let i = 0; i < 7; i += 1) {
      const x = -r * 0.64 + i * r * 0.213;
      ctx.beginPath();
      ctx.moveTo(x, offset);
      ctx.lineTo(x + r * 0.04, offset + depth * r * 0.15);
      ctx.stroke();
    }
    ctx.fillStyle = "rgba(255, 255, 236, 0.45)";
    ellipse(ctx, 0, y, r * 0.08, r * 0.028);
    ctx.fill();
  } else if (type === FRUIT_TYPES.kiwi) {
    for (let i = 0; i < 8; i += 1) {
      const x = -r * 0.54 + (i / 7) * r * 1.08;
      ctx.fillStyle = type.pip;
      ellipse(ctx, x, y + depth * ((i % 2) * r * 0.055), r * 0.022, r * 0.043);
      ctx.fill();
    }
    ctx.fillStyle = "rgba(255, 252, 218, 0.54)";
    ellipse(ctx, 0, y, r * 0.16, r * 0.04);
    ctx.fill();
  } else if (type === FRUIT_TYPES.apple) {
    ctx.fillStyle = type.pip;
    ellipse(ctx, -r * 0.11, y + depth * r * 0.03, r * 0.026, r * 0.05);
    ctx.fill();
    ellipse(ctx, r * 0.11, y + depth * r * 0.03, r * 0.026, r * 0.05);
    ctx.fill();
  } else if (type === FRUIT_TYPES.plum) {
    ctx.fillStyle = type.pip;
    ellipse(ctx, 0, y + depth * r * 0.02, r * 0.19, r * 0.055);
    ctx.fill();
    ctx.strokeStyle = "rgba(255, 218, 160, 0.18)";
    ctx.lineWidth = Math.max(1, r * 0.018);
    ctx.stroke();
  } else if (type === FRUIT_TYPES.pomegranate) {
    for (let i = 0; i < 12; i += 1) {
      const x = -r * 0.58 + (i / 11) * r * 1.16;
      ctx.fillStyle = i % 3 === 0 ? "#ffd56a" : "#a80f32";
      ellipse(ctx, x, y + depth * ((i % 2) * r * 0.045), r * 0.024, r * 0.035);
      ctx.fill();
    }
  }

  ctx.restore();
}

function drawCutFace(ctx, type, r, offset, side) {
  const depth = side > 0 ? 1 : -1;
  const length = r * 0.87;
  const bulge = r * 0.155;

  ctx.save();
  ctx.beginPath();
  ctx.moveTo(-length, offset);
  ctx.quadraticCurveTo(0, offset + bulge * 1.35 * depth, length, offset);
  ctx.quadraticCurveTo(0, offset + bulge * 0.22 * depth, -length, offset);
  ctx.closePath();
  ctx.fillStyle = cutFaceGradient(ctx, r, type);
  ctx.fill();

  ctx.strokeStyle = type.rind;
  ctx.globalAlpha = 0.88;
  ctx.lineWidth = Math.max(1.5, r * 0.045);
  ctx.beginPath();
  ctx.moveTo(-length, offset);
  ctx.quadraticCurveTo(0, offset + bulge * 1.35 * depth, length, offset);
  ctx.stroke();
  ctx.globalAlpha = 1;

  ctx.strokeStyle = "rgba(255, 255, 255, 0.16)";
  ctx.lineWidth = Math.max(1, r * 0.014);
  ctx.beginPath();
  ctx.moveTo(-length * 0.9, offset + depth * r * 0.012);
  ctx.quadraticCurveTo(0, offset + bulge * 1.12 * depth, length * 0.9, offset + depth * r * 0.012);
  ctx.stroke();

  drawCutDetails(ctx, type, r, offset, side);
  ctx.restore();
}

export function drawHalf(ctx, half) {
  const type = FRUIT_TYPES[half.type];
  const r = half.radius;
  ctx.save();
  ctx.globalAlpha = half.alpha;
  ctx.translate(half.x, half.y);
  ctx.rotate(half.rot);
  ctx.rotate(half.cutLocal);

  ctx.beginPath();
  if (half.side > 0) {
    ctx.rect(-r * 2, half.offset, r * 4, r * 2.1);
  } else {
    ctx.rect(-r * 2, half.offset - r * 2.1, r * 4, r * 2.1);
  }
  ctx.clip();
  ctx.rotate(-half.cutLocal);

  drawBody(ctx, type, r, half.seed, type.shape, false);

  ctx.rotate(half.cutLocal);
  drawCutFace(ctx, type, r, half.offset, half.side);
  ctx.restore();
}

export function drawBomb(ctx, bomb, time) {
  const r = bomb.radius;
  ctx.save();
  ctx.translate(bomb.x, bomb.y);
  ctx.rotate(bomb.rot);

  const glow = ctx.createRadialGradient(0, 0, r * 0.1, 0, 0, r * 2.1);
  glow.addColorStop(0, "rgba(255, 70, 40, 0.18)");
  glow.addColorStop(0.52, "rgba(208, 36, 38, 0.08)");
  glow.addColorStop(1, "rgba(160, 20, 30, 0)");
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(0, 0, r * 2.1, 0, TAU);
  ctx.fill();

  ctx.shadowColor = "rgba(0, 0, 0, 0.65)";
  ctx.shadowBlur = r * 0.7;
  ctx.shadowOffsetY = r * 0.22;

  const iron = ctx.createRadialGradient(-r * 0.35, -r * 0.42, r * 0.08, 0, 0, r * 1.15);
  iron.addColorStop(0, "#56505a");
  iron.addColorStop(0.26, "#2c2932");
  iron.addColorStop(0.68, "#16141c");
  iron.addColorStop(1, "#07060a");
  ctx.fillStyle = iron;
  ctx.beginPath();
  ctx.arc(0, 0, r, 0, TAU);
  ctx.fill();
  ctx.shadowColor = "transparent";

  ctx.strokeStyle = "rgba(255, 226, 196, 0.16)";
  ctx.lineWidth = Math.max(1, r * 0.035);
  ctx.beginPath();
  ctx.arc(0, 0, r * 0.88, -2.65, -0.62);
  ctx.stroke();

  ctx.strokeStyle = "rgba(159, 40, 47, 0.75)";
  ctx.lineWidth = r * 0.11;
  ctx.beginPath();
  ctx.arc(0, 0, r * 0.18, 0, TAU);
  ctx.stroke();

  ctx.fillStyle = "rgba(209, 48, 52, 0.9)";
  ctx.font = `600 ${Math.round(r * 0.54)}px "Hiragino Mincho ProN", "Yu Mincho", serif`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText("爆", 0, r * 0.025);
  ctx.strokeStyle = "rgba(255, 159, 120, 0.28)";
  ctx.lineWidth = Math.max(1, r * 0.018);
  ctx.beginPath();
  ctx.arc(0, r * 0.02, r * 0.46, 0, TAU);
  ctx.stroke();

  ctx.strokeStyle = "#5f442f";
  ctx.lineWidth = Math.max(2.5, r * 0.085);
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(r * 0.27, -r * 0.88);
  ctx.bezierCurveTo(r * 0.6, -r * 1.14, r * 0.38, -r * 1.36, r * 0.5, -r * 1.55);
  ctx.stroke();
  ctx.strokeStyle = "#d3a36b";
  ctx.lineWidth = Math.max(1, r * 0.02);
  ctx.beginPath();
  ctx.moveTo(r * 0.28, -r * 0.9);
  ctx.bezierCurveTo(r * 0.6, -r * 1.14, r * 0.4, -r * 1.35, r * 0.5, -r * 1.52);
  ctx.stroke();

  const flicker = 0.68 + Math.sin(time * 23 + bomb.seed) * 0.2 + Math.sin(time * 41) * 0.1;
  const sparkX = r * 0.5;
  const sparkY = -r * 1.58;
  const sparkGlow = ctx.createRadialGradient(sparkX, sparkY, 0, sparkX, sparkY, r * 0.55);
  sparkGlow.addColorStop(0, `rgba(255, 247, 207, ${flicker})`);
  sparkGlow.addColorStop(0.25, `rgba(255, 170, 65, ${flicker * 0.8})`);
  sparkGlow.addColorStop(1, "rgba(255, 80, 20, 0)");
  ctx.fillStyle = sparkGlow;
  ctx.beginPath();
  ctx.arc(sparkX, sparkY, r * 0.55, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#fff8dc";
  ctx.beginPath();
  ctx.arc(sparkX, sparkY, r * 0.085, 0, TAU);
  ctx.fill();

  ctx.restore();
}

const TAU = Math.PI * 2;

function seeded(seed = 17) {
  let value = seed >>> 0;
  return () => {
    value = (value * 1664525 + 1013904223) >>> 0;
    return value / 4294967296;
  };
}

function glow(ctx, x, y, radius, color, alpha = 1) {
  const gradient = ctx.createRadialGradient(x, y, 0, x, y, radius);
  gradient.addColorStop(0, color.replace("ALPHA", String(alpha)));
  gradient.addColorStop(0.38, color.replace("ALPHA", String(alpha * 0.4)));
  gradient.addColorStop(1, color.replace("ALPHA", "0"));
  ctx.fillStyle = gradient;
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, TAU);
  ctx.fill();
}

function drawStar(ctx, x, y, size, alpha) {
  ctx.fillStyle = `rgba(255, 239, 208, ${alpha})`;
  ctx.beginPath();
  ctx.arc(x, y, size, 0, TAU);
  ctx.fill();
  if (size > 1.1) {
    ctx.strokeStyle = `rgba(255, 239, 208, ${alpha * 0.4})`;
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(x - size * 3.4, y);
    ctx.lineTo(x + size * 3.4, y);
    ctx.moveTo(x, y - size * 3.4);
    ctx.lineTo(x, y + size * 3.4);
    ctx.stroke();
  }
}

function drawMoon(ctx, w, h, random, scale) {
  const x = w * 0.775;
  const y = h * 0.205;
  const r = Math.min(w, h) * 0.098 * scale;

  glow(ctx, x, y, r * 3.8, "rgba(255, 202, 137, ALPHA)", 0.13);
  glow(ctx, x, y, r * 1.9, "rgba(255, 224, 177, ALPHA)", 0.2);

  const moon = ctx.createRadialGradient(x - r * 0.28, y - r * 0.33, r * 0.08, x, y, r * 1.05);
  moon.addColorStop(0, "#fff8df");
  moon.addColorStop(0.58, "#f2d7a4");
  moon.addColorStop(0.88, "#d6a96f");
  moon.addColorStop(1, "#b7824d");
  ctx.fillStyle = moon;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  ctx.fill();

  ctx.save();
  ctx.beginPath();
  ctx.arc(x, y, r * 0.98, 0, TAU);
  ctx.clip();
  for (let i = 0; i < 13; i += 1) {
    const cx = x + (random() - 0.5) * r * 1.5;
    const cy = y + (random() - 0.5) * r * 1.5;
    const cr = r * (0.025 + random() * 0.1);
    ctx.fillStyle = `rgba(139, 100, 66, ${0.04 + random() * 0.08})`;
    ctx.beginPath();
    ctx.arc(cx, cy, cr, 0, TAU);
    ctx.fill();
  }
  const haze = ctx.createLinearGradient(x - r, y - r, x + r, y + r);
  haze.addColorStop(0, "rgba(255, 246, 222, 0.07)");
  haze.addColorStop(0.5, "rgba(255, 246, 222, 0)");
  haze.addColorStop(1, "rgba(128, 81, 52, 0.15)");
  ctx.fillStyle = haze;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
  ctx.restore();

  const cloud = ctx.createLinearGradient(x - r * 2.5, y, x + r * 2.5, y);
  cloud.addColorStop(0, "rgba(17, 14, 25, 0)");
  cloud.addColorStop(0.25, "rgba(17, 14, 25, 0.2)");
  cloud.addColorStop(0.52, "rgba(27, 20, 31, 0.46)");
  cloud.addColorStop(0.76, "rgba(17, 14, 25, 0.2)");
  cloud.addColorStop(1, "rgba(17, 14, 25, 0)");
  ctx.fillStyle = cloud;
  ctx.beginPath();
  ctx.moveTo(x - r * 2.7, y + r * 0.11);
  ctx.bezierCurveTo(x - r * 1.2, y - r * 0.32, x - r * 0.2, y + r * 0.34, x + r * 0.9, y + r * 0.04);
  ctx.bezierCurveTo(x + r * 1.6, y - r * 0.17, x + r * 2.1, y + r * 0.24, x + r * 2.8, y + r * 0.1);
  ctx.lineTo(x + r * 2.8, y + r * 0.32);
  ctx.bezierCurveTo(x + r * 1.7, y + r * 0.42, x + r * 0.7, y + r * 0.2, x, y + r * 0.42);
  ctx.bezierCurveTo(x - r * 0.9, y + r * 0.3, x - r * 1.8, y + r * 0.48, x - r * 2.7, y + r * 0.36);
  ctx.closePath();
  ctx.fill();
}

function drawMountains(ctx, w, h, random) {
  const layers = [
    {
      y: h * 0.63,
      color: "#171523",
      edge: "rgba(205, 132, 91, 0.08)",
      amplitude: 0.15,
      step: 0.09
    },
    {
      y: h * 0.72,
      color: "#12121c",
      edge: "rgba(225, 154, 103, 0.06)",
      amplitude: 0.11,
      step: 0.13
    },
    {
      y: h * 0.81,
      color: "#0b0b13",
      edge: "rgba(225, 154, 103, 0.04)",
      amplitude: 0.07,
      step: 0.18
    }
  ];

  layers.forEach((layer, index) => {
    ctx.beginPath();
    ctx.moveTo(-10, h + 10);
    ctx.lineTo(-10, layer.y);
    let x = -10;
    let peak = false;
    while (x < w + 20) {
      const step = w * (layer.step * (0.55 + random() * 0.8));
      x += step;
      const y = layer.y - (peak ? h * layer.amplitude * (0.45 + random() * 0.8) : h * layer.amplitude * 0.07);
      ctx.lineTo(x, y);
      peak = !peak;
    }
    ctx.lineTo(w + 20, h + 10);
    ctx.closePath();
    ctx.fillStyle = layer.color;
    ctx.fill();

    ctx.strokeStyle = layer.edge;
    ctx.lineWidth = 1;
    ctx.beginPath();
    let sx = -10;
    let sy = layer.y;
    for (let i = 0; i < 11; i += 1) {
      sx += w / 10 * (0.75 + random() * 0.5);
      sy = layer.y - h * layer.amplitude * (0.16 + random() * 0.38);
      ctx.lineTo(sx, sy);
    }
    ctx.stroke();
  });
}

function drawTorii(ctx, w, h, scale) {
  const x = w * 0.175;
  const baseY = h * 0.845;
  const height = h * 0.31 * scale;
  const topY = baseY - height;
  const half = w * 0.088 * scale;

  ctx.save();
  ctx.translate(x, 0);

  const body = ctx.createLinearGradient(0, topY, 0, baseY);
  body.addColorStop(0, "#25151c");
  body.addColorStop(0.55, "#180f15");
  body.addColorStop(1, "#0a080d");
  ctx.fillStyle = body;

  ctx.fillRect(-half * 0.82, topY + height * 0.15, half * 1.64, height * 0.85);
  ctx.fillStyle = "#0a080d";
  ctx.fillRect(-half * 0.82, topY + height * 0.15, half * 1.64, height * 0.06);

  ctx.fillStyle = "#25151c";
  ctx.beginPath();
  ctx.moveTo(-half * 0.62, topY + height * 0.08);
  ctx.lineTo(-half * 0.42, topY);
  ctx.lineTo(-half * 0.24, topY + height * 0.08);
  ctx.lineTo(-half * 0.24, baseY);
  ctx.lineTo(-half * 0.43, baseY);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(half * 0.62, topY + height * 0.08);
  ctx.lineTo(half * 0.42, topY);
  ctx.lineTo(half * 0.24, topY + height * 0.08);
  ctx.lineTo(half * 0.24, baseY);
  ctx.lineTo(half * 0.43, baseY);
  ctx.closePath();
  ctx.fill();

  ctx.strokeStyle = "rgba(218, 151, 102, 0.16)";
  ctx.lineWidth = Math.max(1, w * 0.0009);
  ctx.beginPath();
  ctx.moveTo(-half * 0.62, topY + height * 0.09);
  ctx.lineTo(-half * 0.27, topY + height * 0.09);
  ctx.moveTo(half * 0.27, topY + height * 0.09);
  ctx.lineTo(half * 0.62, topY + height * 0.09);
  ctx.stroke();

  ctx.fillStyle = "#21131a";
  ctx.beginPath();
  ctx.moveTo(-half * 1.28, topY + height * 0.08);
  ctx.quadraticCurveTo(-half * 0.78, topY - height * 0.045, 0, topY - height * 0.015);
  ctx.quadraticCurveTo(half * 0.78, topY - height * 0.045, half * 1.28, topY + height * 0.08);
  ctx.lineTo(half * 1.19, topY + height * 0.13);
  ctx.quadraticCurveTo(half * 0.6, topY + height * 0.025, 0, topY + height * 0.04);
  ctx.quadraticCurveTo(-half * 0.6, topY + height * 0.025, -half * 1.19, topY + height * 0.13);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = "#1d1118";
  ctx.beginPath();
  ctx.moveTo(-half * 1.07, topY + height * 0.19);
  ctx.lineTo(half * 1.07, topY + height * 0.19);
  ctx.lineTo(half * 1.0, topY + height * 0.24);
  ctx.lineTo(-half * 1.0, topY + height * 0.24);
  ctx.closePath();
  ctx.fill();

  ctx.strokeStyle = "rgba(242, 178, 116, 0.22)";
  ctx.lineWidth = Math.max(1, w * 0.0012);
  ctx.beginPath();
  ctx.moveTo(-half * 1.2, topY + height * 0.083);
  ctx.quadraticCurveTo(0, topY - height * 0.012, half * 1.2, topY + height * 0.083);
  ctx.stroke();

  ctx.fillStyle = "#1d1118";
  ctx.fillRect(-half * 0.085, topY + height * 0.24, half * 0.17, height * 0.11);
  ctx.fillRect(-half * 0.7, topY + height * 0.48, half * 1.4, height * 0.028);

  glow(ctx, 0, topY + height * 0.39, height * 0.18, "rgba(255, 153, 74, ALPHA)", 0.055);

  ctx.restore();
}

function drawBamboo(ctx, w, h, random) {
  const clusters = [
    { x: w * 0.045, scale: 1.1, alpha: 0.7 },
    { x: w * 0.075, scale: 0.82, alpha: 0.42 },
    { x: w * 0.965, scale: 1.0, alpha: 0.5 }
  ];
  clusters.forEach((cluster) => {
    const stalks = 5;
    for (let i = 0; i < stalks; i += 1) {
      const x = cluster.x + (random() - 0.5) * w * 0.055 * cluster.scale;
      const top = h * (0.65 - random() * 0.32) - (cluster.x > w * 0.9 ? h * 0.08 : 0);
      const bottom = h * 0.92;
      const width = (2.2 + random() * 2.1) * cluster.scale;
      ctx.strokeStyle = `rgba(31, 39, 30, ${cluster.alpha})`;
      ctx.lineWidth = width;
      ctx.beginPath();
      ctx.moveTo(x, bottom);
      ctx.quadraticCurveTo(x + (random() - 0.5) * 8, (top + bottom) / 2, x + (random() - 0.5) * 20, top);
      ctx.stroke();

      for (let leaf = 0; leaf < 4; leaf += 1) {
        const ly = top + random() * (bottom - top) * 0.48;
        const dir = random() > 0.5 ? 1 : -1;
        ctx.fillStyle = `rgba(25, 35, 26, ${cluster.alpha * 0.6})`;
        ctx.beginPath();
        ctx.ellipse(
          x + dir * (8 + random() * 24),
          ly,
          16 + random() * 19,
          2.3 + random() * 2,
          dir * (0.24 + random() * 0.4),
          0,
          TAU
        );
        ctx.fill();
      }
    }
  });
}

function drawPavilion(ctx, w, h) {
  const x = w * 0.86;
  const y = h * 0.77;
  const s = Math.min(w, h) * 0.001;

  ctx.save();
  ctx.translate(x, y);
  ctx.fillStyle = "#090910";
  ctx.fillRect(-70 * s, 5 * s, 140 * s, 100 * s);
  for (let i = 0; i < 4; i += 1) {
    const yy = i * 18 * s;
    ctx.fillStyle = "#0b0b13";
    ctx.beginPath();
    ctx.moveTo(-90 * s, yy);
    ctx.quadraticCurveTo(0, yy - 19 * s, 90 * s, yy);
    ctx.lineTo(72 * s, yy + 6 * s);
    ctx.quadraticCurveTo(0, yy - 8 * s, -72 * s, yy + 6 * s);
    ctx.closePath();
    ctx.fill();
  }
  ctx.strokeStyle = "rgba(220, 149, 94, 0.08)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-90 * s, 0);
  ctx.quadraticCurveTo(0, -16 * s, 90 * s, 0);
  ctx.stroke();
  ctx.restore();
}

function drawBranch(ctx, w, h, random) {
  ctx.save();
  ctx.strokeStyle = "rgba(18, 14, 22, 0.88)";
  ctx.lineCap = "round";
  const startX = -w * 0.015;
  const startY = h * 0.08;
  ctx.lineWidth = w * 0.007;
  ctx.beginPath();
  ctx.moveTo(startX, startY);
  ctx.bezierCurveTo(w * 0.1, h * 0.075, w * 0.16, h * 0.18, w * 0.29, h * 0.15);
  ctx.stroke();

  ctx.lineWidth = w * 0.0035;
  ctx.beginPath();
  ctx.moveTo(w * 0.12, h * 0.105);
  ctx.bezierCurveTo(w * 0.17, h * 0.05, w * 0.24, h * 0.055, w * 0.28, h * 0.02);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(w * 0.18, h * 0.135);
  ctx.quadraticCurveTo(w * 0.18, h * 0.21, w * 0.23, h * 0.25);
  ctx.stroke();

  const blossoms = [
    [0.055, 0.095], [0.078, 0.12], [0.105, 0.087], [0.13, 0.125], [0.165, 0.083],
    [0.17, 0.155], [0.205, 0.12], [0.23, 0.09], [0.248, 0.155], [0.265, 0.05],
    [0.205, 0.205], [0.225, 0.235], [0.29, 0.14]
  ];
  blossoms.forEach(([px, py], index) => {
    const x = w * px + (random() - 0.5) * 10;
    const y = h * py + (random() - 0.5) * 10;
    const r = 3.2 + random() * 4.4;
    const alpha = 0.22 + random() * 0.3;
    ctx.fillStyle = `rgba(243, 173, 181, ${alpha})`;
    for (let p = 0; p < 5; p += 1) {
      const angle = (p / 5) * TAU + index * 0.31;
      ctx.beginPath();
      ctx.ellipse(x + Math.cos(angle) * r * 0.7, y + Math.sin(angle) * r * 0.7, r * 0.62, r * 0.38, angle, 0, TAU);
      ctx.fill();
    }
    ctx.fillStyle = `rgba(247, 213, 155, ${alpha * 1.25})`;
    ctx.beginPath();
    ctx.arc(x, y, r * 0.2, 0, TAU);
    ctx.fill();
  });
  ctx.restore();
}

function drawLanterns(ctx, w, h) {
  const lanterns = [
    { x: w * 0.325, y: h * 0.18, r: 10, glow: 44 },
    { x: w * 0.36, y: h * 0.33, r: 7, glow: 33 },
    { x: w * 0.685, y: h * 0.12, r: 7, glow: 31 }
  ];

  ctx.save();
  ctx.strokeStyle = "rgba(24, 17, 21, 0.5)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(w * 0.31, 0);
  ctx.quadraticCurveTo(w * 0.31, h * 0.12, w * 0.325, h * 0.165);
  ctx.moveTo(w * 0.348, 0);
  ctx.quadraticCurveTo(w * 0.35, h * 0.22, w * 0.36, h * 0.315);
  ctx.moveTo(w * 0.68, 0);
  ctx.quadraticCurveTo(w * 0.68, h * 0.08, w * 0.685, h * 0.105);
  ctx.stroke();

  lanterns.forEach((lantern) => {
    glow(ctx, lantern.x, lantern.y, lantern.glow, "rgba(255, 151, 80, ALPHA)", 0.2);
    const body = ctx.createRadialGradient(
      lantern.x - lantern.r * 0.3,
      lantern.y - lantern.r * 0.35,
      0,
      lantern.x,
      lantern.y,
      lantern.r
    );
    body.addColorStop(0, "#ffd49e");
    body.addColorStop(0.45, "#f39a5c");
    body.addColorStop(0.8, "#ac4931");
    body.addColorStop(1, "#6e2826");
    ctx.fillStyle = body;
    ctx.beginPath();
    ctx.ellipse(lantern.x, lantern.y, lantern.r * 0.9, lantern.r, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = "rgba(255, 225, 174, 0.25)";
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(lantern.x - lantern.r * 0.62, lantern.y - lantern.r * 0.62);
    ctx.quadraticCurveTo(lantern.x, lantern.y + lantern.r * 0.3, lantern.x + lantern.r * 0.62, lantern.y - lantern.r * 0.62);
    ctx.stroke();
    ctx.fillStyle = "rgba(50, 22, 19, 0.55)";
    ctx.fillRect(lantern.x - lantern.r * 0.36, lantern.y - lantern.r * 1.09, lantern.r * 0.72, lantern.r * 0.18);
    ctx.fillRect(lantern.x - lantern.r * 0.36, lantern.y + lantern.r * 0.91, lantern.r * 0.72, lantern.r * 0.18);
  });
  ctx.restore();
}

function drawGround(ctx, w, h, random) {
  const ground = ctx.createLinearGradient(0, h * 0.79, 0, h);
  ground.addColorStop(0, "rgba(9, 9, 16, 0)");
  ground.addColorStop(0.32, "rgba(10, 9, 15, 0.34)");
  ground.addColorStop(1, "rgba(5, 5, 9, 0.92)");
  ctx.fillStyle = ground;
  ctx.fillRect(0, h * 0.76, w, h * 0.24);

  const haze = ctx.createLinearGradient(0, h * 0.74, 0, h * 0.9);
  haze.addColorStop(0, "rgba(222, 131, 83, 0)");
  haze.addColorStop(0.55, "rgba(186, 101, 71, 0.055)");
  haze.addColorStop(1, "rgba(222, 131, 83, 0)");
  ctx.fillStyle = haze;
  ctx.fillRect(0, h * 0.72, w, h * 0.2);

  for (let i = 0; i < 28; i += 1) {
    const x = random() * w;
    const y = h * (0.83 + random() * 0.16);
    const width = 20 + random() * 90;
    ctx.strokeStyle = `rgba(187, 133, 93, ${0.018 + random() * 0.04})`;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + width, y + 0.5);
    ctx.stroke();
  }

  ctx.lineWidth = 1;
  for (let i = 0; i < 36; i += 1) {
    const x = random() * w;
    const hh = 8 + random() * 45;
    ctx.strokeStyle = "rgba(7, 8, 11, 0.9)";
    ctx.beginPath();
    ctx.moveTo(x, h);
    ctx.quadraticCurveTo(x + (random() - 0.5) * 14, h - hh * 0.5, x + (random() - 0.5) * 30, h - hh);
    ctx.stroke();
  }
}

function drawDust(ctx, w, h, random) {
  for (let i = 0; i < 90; i += 1) {
    const x = random() * w;
    const y = random() * h;
    const r = 0.4 + random() * 1.5;
    const alpha = 0.025 + random() * 0.07;
    ctx.fillStyle = `rgba(255, 223, 172, ${alpha})`;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fill();
  }
}

export function makeBackground(width, height, dpr = 1) {
  const canvas = document.createElement("canvas");
  canvas.width = Math.max(1, Math.round(width * dpr));
  canvas.height = Math.max(1, Math.round(height * dpr));
  const ctx = canvas.getContext("2d");
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  const random = seeded(Math.round(width * 7 + height * 13));
  const w = width;
  const h = height;

  const sky = ctx.createLinearGradient(0, 0, 0, h);
  sky.addColorStop(0, "#06070e");
  sky.addColorStop(0.3, "#0c0c18");
  sky.addColorStop(0.58, "#1a1220");
  sky.addColorStop(0.79, "#2a1822");
  sky.addColorStop(1, "#0b0911");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, w, h);

  const upperGlow = ctx.createRadialGradient(w * 0.72, h * 0.11, 0, w * 0.72, h * 0.11, w * 0.6);
  upperGlow.addColorStop(0, "rgba(126, 73, 70, 0.16)");
  upperGlow.addColorStop(0.5, "rgba(59, 36, 49, 0.06)");
  upperGlow.addColorStop(1, "rgba(0, 0, 0, 0)");
  ctx.fillStyle = upperGlow;
  ctx.fillRect(0, 0, w, h);

  for (let i = 0; i < 145; i += 1) {
    const x = random() * w;
    const y = random() * h * 0.65;
    const big = random() > 0.955;
    drawStar(ctx, x, y, big ? 1.6 + random() * 1.2 : 0.25 + random() * 0.9, 0.1 + random() * (big ? 0.52 : 0.3));
  }

  drawMoon(ctx, w, h, random, 1);
  drawMountains(ctx, w, h, random);
  drawPavilion(ctx, w, h);
  drawTorii(ctx, w, h, 1);
  drawBamboo(ctx, w, h, random);
  drawBranch(ctx, w, h, random);
  drawLanterns(ctx, w, h);
  drawGround(ctx, w, h, random);
  drawDust(ctx, w, h, random);

  const vignette = ctx.createRadialGradient(w * 0.5, h * 0.46, Math.min(w, h) * 0.12, w * 0.5, h * 0.46, Math.max(w, h) * 0.72);
  vignette.addColorStop(0, "rgba(2, 2, 5, 0)");
  vignette.addColorStop(0.62, "rgba(2, 2, 5, 0.1)");
  vignette.addColorStop(1, "rgba(2, 2, 5, 0.62)");
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, w, h);

  return canvas;
}

const STORAGE_KEY = "blade-chain-muted";

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.ambience = null;
    this.noiseBuffer = null;
    this.muted = false;
    try {
      this.muted = localStorage.getItem(STORAGE_KEY) === "1";
    } catch {
      this.muted = false;
    }
  }

  init() {
    if (this.ctx) {
      this.resume();
      return;
    }
    const Context = window.AudioContext || window.webkitAudioContext;
    if (!Context) return;

    try {
      this.ctx = new Context();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.72;

      const compressor = this.ctx.createDynamicsCompressor();
      compressor.threshold.value = -18;
      compressor.knee.value = 18;
      compressor.ratio.value = 5;
      compressor.attack.value = 0.004;
      compressor.release.value = 0.22;
      this.master.connect(compressor);
      compressor.connect(this.ctx.destination);

      const length = Math.floor(this.ctx.sampleRate * 0.8);
      this.noiseBuffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
      const data = this.noiseBuffer.getChannelData(0);
      for (let i = 0; i < length; i += 1) {
        data[i] = Math.random() * 2 - 1;
      }

      this.startAmbience();
      this.resume();
    } catch {
      this.ctx = null;
    }
  }

  resume() {
    if (this.ctx && this.ctx.state === "suspended") {
      this.ctx.resume().catch(() => {});
    }
  }

  setMuted(muted) {
    this.muted = Boolean(muted);
    try {
      localStorage.setItem(STORAGE_KEY, this.muted ? "1" : "0");
    } catch {}

    if (this.ctx && this.master) {
      const now = this.ctx.currentTime;
      this.master.gain.cancelScheduledValues(now);
      this.master.gain.setTargetAtTime(this.muted ? 0 : 0.72, now, 0.025);
    }
  }

  get isMuted() {
    return this.muted;
  }

  startAmbience() {
    if (!this.ctx || this.ambience) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const bus = ctx.createGain();
    bus.gain.setValueAtTime(0.0001, now);
    bus.gain.exponentialRampToValueAtTime(0.038, now + 2.5);
    bus.connect(this.master);

    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = 420;
    filter.Q.value = 0.6;
    filter.connect(bus);

    [55, 82.5, 110].forEach((frequency, index) => {
      const oscillator = ctx.createOscillator();
      oscillator.type = index === 2 ? "triangle" : "sine";
      oscillator.frequency.value = frequency;
      oscillator.detune.value = index === 1 ? 6 : -4;
      const gain = ctx.createGain();
      gain.gain.value = index === 2 ? 0.08 : 0.15;
      oscillator.connect(gain);
      gain.connect(filter);
      oscillator.start();
    });

    if (this.noiseBuffer) {
      const wind = ctx.createBufferSource();
      wind.buffer = this.noiseBuffer;
      wind.loop = true;
      const windFilter = ctx.createBiquadFilter();
      windFilter.type = "bandpass";
      windFilter.frequency.value = 280;
      windFilter.Q.value = 0.4;
      const windGain = ctx.createGain();
      windGain.gain.value = 0.12;
      wind.connect(windFilter);
      windFilter.connect(windGain);
      windGain.connect(bus);
      wind.start();

      const lfo = ctx.createOscillator();
      lfo.frequency.value = 0.07;
      const lfoGain = ctx.createGain();
      lfoGain.gain.value = 0.08;
      lfo.connect(lfoGain);
      lfoGain.connect(windGain.gain);
      lfo.start();
    }

    this.ambience = bus;
  }

  tone(frequency, duration, type = "sine", volume = 0.08, destination = null, start = 0) {
    if (!this.ctx || !this.master) return;
    const ctx = this.ctx;
    const now = ctx.currentTime + start;
    const oscillator = ctx.createOscillator();
    const gain = ctx.createGain();
    oscillator.type = type;
    oscillator.frequency.setValueAtTime(frequency, now);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    oscillator.connect(gain);
    gain.connect(destination || this.master);
    oscillator.start(now);
    oscillator.stop(now + duration + 0.02);
  }

  slice(chain = 1, pan = 0) {
    if (!this.ctx || !this.master || this.muted) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const panner = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
    const destination = panner || this.master;
    if (panner) {
      panner.pan.value = clamp(pan, -1, 1);
      panner.connect(this.master);
    }

    const source = ctx.createBufferSource();
    source.buffer = this.noiseBuffer;
    const band = ctx.createBiquadFilter();
    band.type = "bandpass";
    band.frequency.setValueAtTime(2400 + Math.min(chain, 18) * 80, now);
    band.frequency.exponentialRampToValueAtTime(520, now + 0.13);
    band.Q.value = 0.8;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.25, now + 0.006);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.15);
    source.connect(band);
    band.connect(gain);
    gain.connect(destination);
    source.start(now);
    source.stop(now + 0.17);

    const thump = ctx.createOscillator();
    const thumpGain = ctx.createGain();
    thump.type = "triangle";
    thump.frequency.setValueAtTime(190 + chain * 4, now);
    thump.frequency.exponentialRampToValueAtTime(70, now + 0.1);
    thumpGain.gain.setValueAtTime(0.08, now);
    thumpGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.12);
    thump.connect(thumpGain);
    thumpGain.connect(destination);
    thump.start(now);
    thump.stop(now + 0.14);

    if (chain > 1) {
      const step = Math.min(chain, 14);
      const pitch = 330 * Math.pow(2, (step % 12) / 12);
      this.tone(pitch, 0.18, "sine", 0.045, destination, 0.008);
      this.tone(pitch * 1.5, 0.12, "triangle", 0.018, destination, 0.012);
    }
  }

  milestone(chain) {
    if (!this.ctx || this.muted) return;
    const steps = [0, 0.055, 0.11, 0.17];
    const base = 220 * Math.pow(2, Math.min(chain / 24, 1));
    const ratios = [1, 1.25, 1.5, 2];
    ratios.forEach((ratio, index) => {
      this.tone(base * ratio, 0.7 - index * 0.07, index === 0 ? "triangle" : "sine", 0.07 - index * 0.01, null, steps[index]);
    });
  }

  bomb() {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const source = ctx.createBufferSource();
    source.buffer = this.noiseBuffer;
    const low = ctx.createBiquadFilter();
    low.type = "lowpass";
    low.frequency.setValueAtTime(1200, now);
    low.frequency.exponentialRampToValueAtTime(90, now + 0.7);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.75, now + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.85);
    source.connect(low);
    low.connect(gain);
    gain.connect(this.master);
    source.start(now);
    source.stop(now + 0.9);

    const oscillator = ctx.createOscillator();
    const oscGain = ctx.createGain();
    oscillator.type = "sine";
    oscillator.frequency.setValueAtTime(105, now);
    oscillator.frequency.exponentialRampToValueAtTime(28, now + 0.62);
    oscGain.gain.setValueAtTime(0.52, now);
    oscGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.8);
    oscillator.connect(oscGain);
    oscGain.connect(this.master);
    oscillator.start(now);
    oscillator.stop(now + 0.84);
  }

  miss() {
    if (!this.ctx || this.muted) return;
    this.tone(150, 0.22, "sine", 0.08);
    this.tone(78, 0.3, "triangle", 0.045, null, 0.025);
  }

  gameOver() {
    if (!this.ctx || this.muted) return;
    const notes = [196, 174.6, 146.8, 130.8];
    notes.forEach((frequency, index) => {
      this.tone(frequency, 1.7 - index * 0.12, "sine", 0.065, null, index * 0.22);
      this.tone(frequency / 2, 1.9 - index * 0.1, "triangle", 0.028, null, index * 0.22);
    });
  }

  click() {
    if (!this.ctx || this.muted) return;
    this.tone(520, 0.09, "sine", 0.035);
    this.tone(780, 0.06, "triangle", 0.018, null, 0.015);
  }

  comboBreak() {
    if (!this.ctx || this.muted) return;
    this.tone(240, 0.16, "sine", 0.035);
    this.tone(180, 0.22, "sine", 0.025, null, 0.06);
  }
}

import { AudioEngine } from "./audio.js";
