const path = require('node:path');
const { chromium } = require(path.join(process.env.HOME, '.local/share/omgithub-playwright/node_modules/playwright'));

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.screenshot({ path: 'screenshots/check-menu.png' });
  await page.getByRole('button', { name: 'Play' }).click();
  await page.waitForTimeout(250);
  await page.evaluate(() => {
    const g = window.__bladeChain;
    g.spawn('watermelon', 420, 470);
    g.spawn('orange', 500, 470);
    g.spawn('dragonfruit', 580, 470);
    g.spawn('plum', 660, 470);
    g.spawn('kiwi', 740, 470);
    g.chain(4);
  });
  await page.mouse.move(360, 470);
  await page.mouse.move(800, 470, { steps: 12 });
  await page.waitForTimeout(80);
  await page.screenshot({ path: 'screenshots/check-cut.png' });
  const snapshot = await page.evaluate(() => window.__bladeChain.snapshot());
  console.log(JSON.stringify(snapshot, null, 2));
  console.log('errors:', errors);

  await page.waitForTimeout(400);
  await page.screenshot({ path: 'screenshots/check-after.png' });
  await browser.close();
})();

