const path = require('node:path');
const { chromium } = require(path.join(process.env.HOME, '.local/share/omgithub-playwright/node_modules/playwright'));

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: 'screenshots/check2-menu.png' });
  await page.getByRole('button', { name: 'Play' }).click();
  await page.waitForTimeout(300);
  await page.evaluate(() => {
    const g = window.__bladeChain;
    g.calm();
    const specs = [
      ['watermelon', 500, 500],
      ['orange', 600, 480],
      ['dragonfruit', 700, 470],
      ['plum', 800, 480],
      ['apple', 900, 500]
    ];
    specs.forEach(([type, x, y]) => g.spawn(type, x, y));
    g.chain(6);
  });
  await page.mouse.move(420, 540);
  await page.mouse.move(980, 450, { steps: 18 });
  await page.evaluate(() => window.__bladeChain.freeze());
  await page.waitForTimeout(50);
  await page.screenshot({ path: 'screenshots/check2-cut.png' });
  console.log(JSON.stringify(await page.evaluate(() => window.__bladeChain.snapshot()), null, 2));
  await page.evaluate(() => window.__bladeChain.unfreeze());
  await page.waitForTimeout(300);
  await page.evaluate(() => window.__bladeChain.freeze());
  await page.screenshot({ path: 'screenshots/check2-after.png' });
  console.log('errors:', errors);
  await browser.close();
})();

