const { chromium, devices } = require(path.join(process.env.HOME, '.local/share/omgithub-playwright/node_modules/playwright'));

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    ...devices['iPhone 13'],
    viewport: { width: 390, height: 844 },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true
  });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1300);
  await page.screenshot({ path: 'screenshots/mobile-menu.png' });
  await page.getByRole('button', { name: 'Play' }).tap();
  await page.waitForTimeout(600);
  await page.evaluate(() => {
    const g = window.__bladeChain;
    g.calm();
    const specs = [
      ['watermelon', 80, 420],
      ['orange', 155, 390],
      ['dragonfruit', 235, 380],
      ['plum', 315, 400],
      ['apple', 260, 560]
    ];
    specs.forEach(([type, x, y]) => g.spawn(type, x, y));
    g.chain(7);
    const fire = (x, y) => window.dispatchEvent(new PointerEvent('pointermove', { clientX: x, clientY: y, bubbles: true }));
    fire(40, 470);
    for (let i = 0; i <= 16; i += 1) {
      const t = i / 16;
      fire(40 + t * 330, 470 - t * 110);
    }
    g.freeze();
  });
  await page.waitForTimeout(100);
  await page.screenshot({ path: 'screenshots/mobile-game.png' });
  console.log('game', JSON.stringify(await page.evaluate(() => window.__bladeChain.snapshot())));
  await page.evaluate(() => window.__bladeChain.unfreeze());
  await page.evaluate(() => window.__bladeChain.pauseGame());
  await page.waitForTimeout(350);
  await page.screenshot({ path: 'screenshots/mobile-pause.png' });
  await page.evaluate(() => { window.__bladeChain.resumeGame(); });
  await page.waitForTimeout(200);
  await page.evaluate(() => window.__bladeChain.finish());
  await page.waitForTimeout(500);
  await page.screenshot({ path: 'screenshots/mobile-over.png' });
  console.log('errors:', errors);
  const boxes = await page.evaluate(() => {
    const pick = (sel) => {
      const el = document.querySelector(sel);
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) };
    };
    return { modal: pick('.over-modal'), actions: pick('.over-modal .modal-actions'), title: pick('#overTitle') };
  });
  console.log('boxes', JSON.stringify(boxes));
  await browser.close();
})();

