const path = require('node:path');
const { chromium } = require(path.join(process.env.HOME, '.local/share/omgithub-playwright/node_modules/playwright'));

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(900);
  await page.getByRole('button', { name: 'Play' }).click();
  await page.waitForTimeout(900);
  await page.evaluate(() => {
    const g = window.__bladeChain;
    g.calm();
    const specs = [
      ['watermelon', 560, 530],
      ['orange', 660, 480],
      ['dragonfruit', 770, 460],
      ['plum', 880, 485],
      ['apple', 970, 530],
      ['kiwi', 720, 340]
    ];
    specs.forEach(([type, x, y]) => g.spawn(type, x, y));
    g.chain(9);
    const fire = (x, y) => window.dispatchEvent(new PointerEvent('pointermove', { clientX: x, clientY: y, bubbles: true }));
    fire(470, 600);
    for (let i = 0; i <= 26; i += 1) {
      const t = i / 26;
      fire(470 + t * 580, 600 - t * 190 - Math.sin(t * Math.PI) * 55);
    }
    g.freeze();
  });
  await page.waitForTimeout(80);
  await page.screenshot({ path: 'screenshots/desktop-cut2.png' });
  await page.evaluate(() => window.__bladeChain.unfreeze());
  await page.waitForTimeout(200);
  await page.evaluate(() => window.__bladeChain.pauseGame());
  await page.waitForTimeout(350);
  await page.screenshot({ path: 'screenshots/desktop-pause.png' });
  await page.evaluate(() => { window.__bladeChain.resumeGame(); window.__bladeChain.finish(); });
  await page.waitForTimeout(450);
  await page.screenshot({ path: 'screenshots/desktop-over.png' });
  console.log('errors:', errors);
  await browser.close();
})();

