  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(900);

  const report = {};
  await page.getByRole('button', { name: 'Play' }).tap();
  await page.waitForTimeout(700);
  report.afterPlay = await page.evaluate(() => window.__bladeChain.mode);

  await page.evaluate(() => {
    const g = window.__bladeChain;
    g.calm();
    g.spawn('watermelon', 100, 470);
    g.spawn('orange', 190, 440);
    g.spawn('dragonfruit', 280, 440);
    g.lives(3);
  });
  await page.waitForTimeout(500);

  const cdp = await context.newCDPSession(page);
  const swipe = async (x1, y1, x2, y2, steps = 12) => {
    await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: x1, y: y1 }] });
    for (let i = 1; i <= steps; i += 1) {
      const t = i / steps;
      await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: x1 + (x2 - x1) * t, y: y1 + (y2 - y1) * t }] });
    }
    await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  };
  await swipe(50, 505, 340, 405);
  await page.waitForTimeout(120);
  report.afterSwipe = await page.evaluate(() => window.__bladeChain.snapshot());
  await page.screenshot({ path: 'screenshots/mobile-touch.png' });

  await page.getByRole('button', { name: 'Pause game' }).tap();
