  report.afterEnd = await page.evaluate(() => window.__bladeChain.mode);
  await page.getByRole('button', { name: 'Back to dojo' }).tap();
  await page.waitForTimeout(500);
  report.afterHome = await page.evaluate(() => window.__bladeChain.mode);

  await page.getByRole('button', { name: 'Play' }).tap();
  await page.waitForTimeout(500);
  report.afterReplay = await page.evaluate(() => window.__bladeChain.mode);
  await page.getByRole('button', { name: 'Mute sound' }).tap();
  await page.waitForTimeout(100);
  const muted = await page.evaluate(() => document.body.classList.contains('is-muted'));
  await page.getByRole('button', { name: 'Unmute sound' }).tap();
  await page.waitForTimeout(100);
  report.muteCycle = [muted, await page.evaluate(() => document.body.classList.contains('is-muted'))];
  report.errors = errors;
  console.log(JSON.stringify(report, null, 2));
  await browser.close();
})();

