  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(900);

  const report = {};
  const mode = () => page.evaluate(() => ({ mode: window.__bladeChain.mode, body: document.body.dataset.mode }));
  await page.getByRole('button', { name: 'Play' }).tap();
  await page.waitForTimeout(700);
  report.afterPlay = await mode();

  await page.evaluate(() => {
    const g = window.__bladeChain;
    g.calm();
    g.spawn('watermelon', 100, 430);
    g.spawn('orange', 190, 410);
    g.spawn('dragonfruit', 280, 420);
    g.spawn('plum', 250, 300);
    g.chain(3);
  });
  await page.waitForTimeout(250);

  const cdp = await context.newCDPSession(page);
  const swipe = async (x1, y1, x2, y2, steps = 12) => {
    await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: x1, y: y1, id: 1 }] });
    for (let i = 1; i <= steps; i += 1) {
      const t = i / steps;
      await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: x1 + (x2 - x1) * t, y: y1 + (y2 - y1) * t, id: 1 }] });
    }
    await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  };
  await swipe(40, 470, 340, 360);
  await page.waitForTimeout(60);
  await page.evaluate(() => window.__bladeChain.freeze());
  report.afterSwipe = await page.evaluate(() => window.__bladeChain.snapshot());
  report.afterSwipeMode = await mode();
  await page.screenshot({ path: 'screenshots/mobile-touch.png' });

  await page.evaluate(() => { window.__bladeChain.unfreeze(); window.__bladeChain.start(); });
  await page.waitForTimeout(600);
  report.afterRestart = await mode();
  await page.getByRole('button', { name: 'Pause game' }).tap();
  await page.waitForTimeout(300);
  report.afterPause = await mode();
  await page.getByRole('button', { name: 'Resume' }).tap();
  await page.waitForTimeout(300);
  report.afterResume = await mode();

  await page.getByRole('button', { name: 'Pause game' }).tap();
  await page.waitForTimeout(250);
  await page.getByRole('button', { name: 'End run' }).tap();
  await page.waitForTimeout(500);
  report.afterEnd = await mode();
  await page.getByRole('button', { name: 'Back to dojo' }).tap();
  await page.waitForTimeout(500);
  report.afterHome = await mode();

  await page.getByRole('button', { name: 'Play' }).tap();
  await page.waitForTimeout(500);
  report.afterReplay = await mode();
  await page.getByRole('button', { name: 'Mute sound' }).tap();
  await page.waitForTimeout(100);
  const muted = await page.evaluate(() => document.body.classList.contains('is-muted'));
  await page.getByRole('button', { name: 'Unmute sound' }).tap();
  await page.waitForTimeout(100);
  report.muteCycle = [muted, await page.evaluate(() => document.body.classList.contains('is-muted'))];
  report.errors = errors;
  console.log(JSON.stringify(report, null, 2));
  await browser.close();
})();

