const path = require('node:path');
const { chromium, devices } = require(path.join(process.env.HOME, '.local/share/omgithub-playwright/node_modules/playwright'));

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ ...devices['iPhone 13'], viewport: { width: 390, height: 844 }, hasTouch: true });
  const page = await context.newPage();
  page.on('pageerror', (e) => console.log('ERR', e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(900);
  await page.getByRole('button', { name: 'Play' }).tap();
  await page.waitForTimeout(600);
  const cdp = await context.newCDPSession(page);

  await page.evaluate(() => {
    const g = window.__bladeChain;
    g.calm();
    g.spawn('orange', 150, 430);
    window.__log = [];
    ['pointerdown', 'pointermove', 'pointerup', 'pointercancel', 'touchstart', 'touchmove', 'touchend'].forEach((type) => {
      window.addEventListener(type, (e) => {
        window.__log.push({ type, cx: Math.round(e.clientX || 0), cy: Math.round(e.clientY || 0), target: e.target && e.target.tagName, pointerType: e.pointerType });
      }, true);
    });
  });
  await page.waitForTimeout(80);
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 100, y: 430, id: 1 }] });
  for (let i = 1; i <= 10; i += 1) {
    await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: 100 + i * 12, y: 430, id: 1 }] });
  }
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  await page.waitForTimeout(100);
  console.log(JSON.stringify(await page.evaluate(() => ({ log: window.__log, snap: window.__bladeChain.snapshot() })), null, 2));
  await browser.close();
})();

