const path = require('node:path');
const { chromium } = require(path.join(process.env.HOME, '.local/share/omgithub-playwright/node_modules/playwright'));

(async () => {
  const browser = await chromium.launch({ headless: true });
  const sizes = [
    ['small', 375, 667],
    ['tablet', 834, 1112],
    ['landscape', 844, 390]
  ];
  for (const [name, width, height] of sizes) {
    const page = await browser.newPage({ viewport: { width, height }, hasTouch: true, isMobile: true });
    const errors = [];
    page.on('pageerror', (e) => errors.push(e.message));
    await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
    await page.waitForTimeout(1100);
    const layout = await page.evaluate(() => {
      const inner = document.querySelector('.menu-inner').getBoundingClientRect();
      const play = document.querySelector('.play-button').getBoundingClientRect();
      const records = document.querySelector('.menu-records').getBoundingClientRect();
      return {
        inner: [Math.round(inner.top), Math.round(inner.bottom)],
        play: [Math.round(play.top), Math.round(play.bottom)],
        records: [Math.round(records.top), Math.round(records.bottom)],
        vh: innerHeight,
        scroll: document.documentElement.scrollHeight
      };
    });
    console.log(name, JSON.stringify(layout), 'errors', errors);
    await page.screenshot({ path: `screenshots/check-${name}-menu.png` });
    await page.getByRole('button', { name: 'Play' }).tap();
    await page.waitForTimeout(600);
    console.log(name, 'mode', await page.evaluate(() => window.__bladeChain.mode));
    await page.screenshot({ path: `screenshots/check-${name}-game.png` });
    await page.close();
  }
  await browser.close();
})();

